import pandas as pd, numpy as np
for eid in [1,2,4,5,7,9,10]:
    try:
        df=pd.read_csv(eval(f"experiment_{eid}_csv"))
        cols=[c for c in df.columns]
        sf = df['SlowFormation'].mean() if 'SlowFormation' in df else None
        cr = df['CapacityRetention'].mean() if 'CapacityRetention' in df else None
        print(eid, "SF=",sf, "CR=",round(cr,2) if cr is not None else None, "cols=",cols)
    except Exception as e:
        print(eid,"err",e)

